const T = aide.THREE;
const AGENTS = [
  { name: 'Marketing', color: '#e0823a', x: -0.3 },
  { name: 'Sales', color: '#3ab06a', x: -0.1 },
  { name: 'Research', color: '#3a8de0', x: 0.1 },
  { name: 'Ops', color: '#a05ad0', x: 0.3 }
];
const CARD_Z = -0.28;
const TASKS = [
  { name: 'Draft launch email', agent: 'Marketing' },
  { name: 'Plan campaign', agent: 'Marketing' },
  { name: 'Follow up leads', agent: 'Sales' },
  { name: 'Update pipeline', agent: 'Sales' },
  { name: 'Survey customers', agent: 'Research' },
  { name: 'Test prototype', agent: 'Research' },
  { name: 'Fix rota', agent: 'Ops' },
  { name: 'Order supplies', agent: 'Ops' }
];

aide.spawn('label', { text: 'Agent work map', position: [0, 0.32, CARD_Z], size: 0.032 });
aide.spawn('label', { text: 'Pinch a task, drop on agent', position: [0, 0.27, CARD_Z], size: 0.025 });

for (const a of AGENTS) {
  a.card = aide.spawn('box', { size: [0.18, 0.12, 0.012], color: a.color, position: [a.x, 0.06, CARD_Z] });
  a.title = aide.spawn('label', { text: a.name, position: [a.x, 0.15, CARD_Z], size: 0.028 });
  a.base = aide.spawn('box', { size: [0.18, 0.01, 0.05], color: '#2f3338', position: [a.x, 0.005, CARD_Z] });
}

for (const t of TASKS) {
  t.card = aide.spawn('box', { size: [0.12, 0.012, 0.04], color: '#f6f3ec', position: [0, 0.02, 0] });
  t.label = aide.spawn('label', { text: t.name, size: 0.025, position: [0, 0.05, 0] });
}

let grabbed = null;
let grabHand = null;
let moves = 0;
const grabOffset = new T.Vector3();

function layout() {
  for (const a of AGENTS) {
    const mine = TASKS.filter((t) => t.agent === a.name && t !== grabbed);
    for (let i = 0; i < mine.length; i++) {
      const t = mine[i];
      const px = a.x;
      const pz = CARD_Z + 0.12 + i * 0.06;
      const py = 0.012 + (i % 2) * 0.002;
      t.card.position.set(px, py, pz);
      t.card.rotation.set(0, 0, 0);
      t.label.position.set(px, py + 0.032, pz + 0.005);
    }
  }
}
layout();

aide.say('Your agent work map is ready. Pinch a task card and drop it on another agent.');
aide.score(0);

aide.onPinch((e) => {
  if (grabbed) return;
  for (const t of TASKS) {
    if (e.object === t.card) {
      grabbed = t;
      grabHand = e.hand;
      grabOffset.copy(t.card.position).sub(e.point);
      aide.sound.pop();
      break;
    }
  }
});

const tmp = new T.Vector3();
aide.onFrame(() => {
  if (!grabbed) return;
  const h = aide.hands[grabHand];
  if (h.visible && h.pinching) {
    tmp.copy(h.pinchPoint).add(grabOffset);
    tmp.x = Math.max(-0.45, Math.min(0.45, tmp.x));
    tmp.z = Math.max(-0.35, Math.min(0.35, tmp.z));
    tmp.y = Math.max(0.03, Math.min(0.4, tmp.y));
    grabbed.card.position.copy(tmp);
    grabbed.label.position.set(tmp.x, tmp.y + 0.035, tmp.z);
    return;
  }
  const t = grabbed;
  grabbed = null;
  let best = null;
  let bestD = 0.16;
  for (const a of AGENTS) {
    const d = Math.hypot(t.card.position.x - a.x, t.card.position.z - (CARD_Z + 0.08));
    if (d < bestD) { best = a; bestD = d; }
  }
  if (best && best.name !== t.agent) {
    const from = t.agent;
    t.agent = best.name;
    moves += 1;
    aide.score(moves);
    aide.spawn('burst', { position: [best.x, 0.08, CARD_Z], color: best.color, count: 18 });
    aide.sound.chime();
    aide.say(t.name + ' moved to ' + best.name + '.');
    aide.emit('task_moved', { task: t.name, to: best.name, from: from });
    if (moves >= 3) {
      aide.done('work map built on plane-3, ' + moves + ' tasks reorganised, last: ' + t.name + ' to ' + best.name);
    }
  } else {
    aide.sound.tick();
  }
  layout();
});
